V.f_pengaturan=el=>{
  const d=FIN.d,bsAcc=d.coa.filter(a=>['Aset','Liabilitas','Ekuitas'].includes(a.t)&&a.k!==3200),dnorm=a=>a.t==='Aset'&&a.k!==1900,get=a=>{const v=d.ob[a.k]||0;return Math.abs(v)&&((dnorm(a)?v:-v))},plug=-Object.values(d.ob).reduce((s,v)=>s+v,0);
  el.innerHTML=`<div class="card"><h3>Periode berjalan</h3><div class="form"><div><label>Bulan berjalan (laporan sampai bulan ini)</label><select class="sel" id="pb">${MN.map((n,i)=>`<option value="${i+1}" ${i+1===d.bulan?'selected':''}>${n} ${d.tahun}</option>`).join('')}</select></div></div></div><div class="card" style="margin-top:16px"><h3>Saldo awal tahun</h3><p style="color:var(--mute);margin:0 0 10px">Isi saldo awal akun neraca (nilai positif di sisi normal; akumulasi penyusutan diisi positif). Laba ditahan terisi otomatis sebagai penyeimbang.</p><div class="tbl"><table><thead><tr><th>Akun</th><th class="n">Saldo awal (Rp)</th></tr></thead><tbody>${bsAcc.map(a=>`<tr><td>${a.k} ${esc(a.n)} <small style="color:var(--mute)">${a.g}</small></td><td class="n"><input class="inp" style="width:170px;text-align:right" type="number" min="0" data-ob="${a.k}" value="${get(a)||''}"></td></tr>`).join('')}<tr><td><b>3200 Laba Ditahan (otomatis)</b></td><td class="n"><b id="plug">${fmt(plug)}</b></td></tr></tbody></table></div></div>
  <div class="card" style="margin-top:16px"><h3>Daftar akun (COA)</h3><div class="tools"><button class="btn pri" id="ac">${ico('plus')} Tambah akun</button><span style="color:var(--mute)">${d.coa.length} akun</span></div></div>
  <div class="card" style="margin-top:16px"><h3>Pelanggan & pemasok</h3><div class="form"><div class="full"><label>Pelanggan (satu per baris: Nama; termin hari)</label><textarea class="inp" id="cu" rows="4">${esc(d.cust.map(c=>c.n+'; '+c.t).join('\n'))}</textarea></div><div class="full"><label>Pemasok (satu per baris: Nama; termin hari)</label><textarea class="inp" id="su" rows="4">${esc(d.supp.map(c=>c.n+'; '+c.t).join('\n'))}</textarea></div></div></div>
  <div class="card" style="margin-top:16px"><h3>Data keuangan</h3><div class="tools"><button class="btn" id="bk">${ico('down')} Cadangkan (JSON)</button><button class="btn" id="rst">Pulihkan dari cadangan</button><button class="btn" id="bl">Mulai dari data kosong</button><button class="btn dng" id="rs">Kembalikan data contoh</button></div><p style="color:var(--mute)">Data tersimpan di komputer ini. Angka pada edisi ini adalah data simulasi. Produk diberikan sebagaimana adanya, tanpa garansi, pembaruan, maupun dukungan.</p></div>`;
  $('#pb').onchange=e=>{d.bulan=+e.target.value;d.sel=d.bulan;FIN.save();toast('Periode berjalan: '+MN[d.bulan-1])};
  $$('[data-ob]',el).forEach(i=>i.onchange=()=>{if(d.lock){toast('Saldo awal terkunci karena sudah ada periode yang ditutup');return V.f_pengaturan(el)}const a=FIN.acc(i.dataset.ob),v=Math.max(0,+i.value||0);if(v)d.ob[a.k]=dnorm(a)?v:-v;else delete d.ob[a.k];FIN.save();$('#plug').textContent=fmt(-Object.values(d.ob).reduce((s,x)=>s+x,0));toast('Saldo awal disimpan')});
  const parse=t=>t.split('\n').map(x=>x.split(';')).filter(x=>x[0].trim()).map(x=>({n:x[0].trim(),t:+x[1]||30}));
  $('#cu').onchange=e=>{d.cust=parse(e.target.value);FIN.save();toast('Pelanggan disimpan')};$('#su').onchange=e=>{d.supp=parse(e.target.value);FIN.save();toast('Pemasok disimpan')};
  $('#ac').onclick=()=>{if(DEMO())return lock('Tambah akun');modal('Tambah akun',`<div class="form"><div><label>Kode (angka)</label><input class="inp" type="number" id="a_k"></div><div><label>Nama akun</label><input class="inp" id="a_n"></div><div><label>Tipe</label><select class="sel" id="a_t">${opts(['Aset','Liabilitas','Ekuitas','Pendapatan','HPP','Beban','Lain-lain'])}</select></div><div><label>Kelompok</label><select class="sel" id="a_g">${opts(['Aset Lancar','Aset Tetap','Liabilitas Jangka Pendek','Liabilitas Jangka Panjang','Ekuitas','Pendapatan','HPP','Beban Operasional','Pendapatan/Beban Lain'])}</select></div></div>`,{buttons:[{text:'Batal'},{text:'Simpan',cls:'pri',fn:()=>{const k=+$('#a_k').value,n=$('#a_n').value.trim();if(!k||!n){toast('Kode dan nama wajib diisi');return false}if(d.coa.some(a=>a.k===k)){toast('Kode sudah ada');return false}d.coa.push({k,n,t:$('#a_t').value,g:$('#a_g').value});d.coa.sort((a,b)=>a.k-b.k);FIN.save();V.f_pengaturan(el);toast('Akun ditambahkan')}}]})};
  $('#rst').onclick=gate('Pulihkan cadangan',()=>pickBackup('Finance',j=>j&&Array.isArray(j.ent)&&Array.isArray(j.coa),j=>{FIN.d=j;FIN.save();App.render()}));
  $('#bk').onclick=gate('Cadangan data',()=>download('finance-cadangan.json',JSON.stringify(FIN.d),'application/json'));
  $('#bl').onclick=gate('Mulai dari data kosong',()=>{if(confirm('Semua jurnal, faktur, pembayaran, dan aset contoh dihapus. Isi saldo awal setelahnya. Lanjutkan?')){FIN.blank();App.render();toast('Data dikosongkan. Isi saldo awal di sini.')}});
  $('#rs').onclick=()=>{if(confirm('Semua perubahan akan hilang. Lanjutkan?')){FIN.reset();App.render();toast('Data contoh dikembalikan')}};
};

V.f_tutup=el=>{
  if(DEMO())return lockPage(el,'Tutup buku & kunci periode','Periksa kelengkapan jurnal lalu kunci periode agar angka laporan tidak berubah. Tersedia di edisi lengkap.');
  const d=FIN.d,lk=d.lock||'',lm=lk?+lk.slice(5,7):0,nm=lm+1,draw=()=>V.f_tutup(el);
  const chk=m=>{const end=FIN.end(m),s=FIN.start(m),r=[];
   const unb=d.ent.filter(e=>e.l.reduce((a,x)=>a+x[1]-x[2],0)!==0).length;
   r.push({t:'Semua jurnal seimbang (debit = kredit)',ok:!unb,n:unb?unb+' jurnal tidak seimbang':'',blk:1});
   const ns=FIN.neraca(m).selisih;r.push({t:'Neraca akhir bulan seimbang',ok:ns===0,n:ns?'Selisih '+idr(ns):'',blk:1});
   let md=0;d.aset.forEach(a=>{const c=asetCalc(a,m);if(c.k>=1&&c.k<=a.umur&&c.mo&&!d.ent.some(e=>e.no===`DEP-${a.kode}-${String(m).padStart(2,'0')}`))md++});
   r.push({t:'Penyusutan aset tetap sudah diposting',ok:!md,n:md?md+' aset belum disusutkan (menu Aset Tetap)':'',blk:1});
   let ml=0;d.loans.forEach(l=>loanSched(l).forEach(x=>{if(x.d>=s&&x.d<=end&&!d.ent.some(e=>e.no===x.no))ml++}));
   r.push({t:'Angsuran pinjaman bulan ini sudah diposting',ok:!ml,n:ml?ml+' angsuran belum diposting (menu Pinjaman)':'',blk:1});
   {const un=d.pph23.filter(b=>b.d>=s&&b.d<=end&&!b.setor).length;r.push({t:'PPh Pasal 23 masa ini sudah disetor',ok:!un,n:un?un+' bukti potong belum disetor (menu PPh Pasal 23)':'',blk:0})}
   {const S=FIN.bkState(m);r.push({t:'Rekonsiliasi bank: tidak ada mutasi bank yang belum dibukukan',ok:!S.bankOnly.length&&!S.selisih,n:S.bankOnly.length?S.bankOnly.length+' mutasi bank belum dibukukan (menu Rekonsiliasi Bank)':S.selisih?'Selisih '+idr(S.selisih):'',blk:0})}
   const kas=FIN.saldoKas(m);r.push({t:'Saldo kas & bank tidak negatif',ok:kas>=0,n:kas<0?'Saldo '+idr(kas)+' — periksa pencatatan':'',blk:0});
   const op=d.jual.concat(d.beli).filter(x=>x.d<=end&&x.d>=s&&!d.ent.some(e=>e.no===x.no&&(e.src==='jual'||e.src==='beli'))).length;
   r.push({t:'Semua faktur bulan ini punya jurnal',ok:!op,n:op?op+' faktur tanpa jurnal':'',blk:1});return r};
  const canClose=nm<=12&&nm<=d.bulan,res=canClose?chk(nm):[],pass=res.every(x=>x.ok||!x.blk);
  el.innerHTML=`<div class="grid g2"><div class="card"><h3>Status periode</h3><p style="margin:0 0 10px">${lk?`Dikunci sampai akhir <b>${MN[lm-1]} ${d.tahun}</b>. Transaksi bertanggal pada atau sebelum itu tidak bisa ditambah, diubah, atau dihapus.`:'Belum ada periode yang ditutup.'}</p>
   <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${MN.map((n,i)=>pill((i<lm?'🔒 ':'')+n.slice(0,3),i<lm?'ok':'mut')).join('')}</div>
   <div class="tools">${lm?`<button class="btn dng" id="op">Buka kembali ${MN[lm-1]}</button>`:''}</div></div>
   <div class="card"><h3>${canClose?'Tutup buku '+MN[nm-1]+' '+d.tahun:'Tutup buku'}</h3>${canClose?`<div style="display:grid;gap:8px;margin-bottom:14px">${res.map(x=>`<div style="display:flex;gap:8px;align-items:flex-start">${pill(x.ok?'Lolos':x.blk?'Gagal':'Periksa',x.ok?'ok':x.blk?'bad':'warn')}<div>${x.t}${x.n?`<br><small style="color:var(--mute)">${esc(x.n)}</small>`:''}</div></div>`).join('')}</div>${nm===12?`<label style="display:flex;gap:8px;align-items:flex-start;margin-bottom:12px"><input type="checkbox" id="cj" checked><span>Posting <b>jurnal penutup tahun</b>: saldo pendapatan dan beban ditutup ke Laba Ditahan. Laporan laba rugi tahun ini tetap utuh.</span></label>`:''}<div class="tools"><button class="btn pri" id="cl" ${pass?'':'disabled'}>Tutup buku ${MN[nm-1]}</button><button class="btn" id="pl">Cetak laba rugi & neraca</button></div>${pass?'':'<p style="color:var(--mute);margin:10px 0 0">Selesaikan pemeriksaan yang gagal untuk dapat menutup periode.</p>'}`:`<p style="color:var(--mute);margin:0">${nm>12?'Seluruh bulan tahun '+d.tahun+' sudah ditutup.':'Bulan berikutnya ('+MN[nm-1]+') belum menjadi periode berjalan. Ubah periode berjalan di Pengaturan Keuangan bila ingin menutupnya.'}</p>`}</div></div>`;
  if($('#cl'))$('#cl').onclick=()=>{if(!confirm('Tutup buku '+MN[nm-1]+'? Transaksi pada periode ini akan terkunci.'))return;if(nm===12&&$('#cj')&&$('#cj').checked&&!d.ent.some(e=>e.src==='tutup')){const c=FIN.closeEntry();if(c)FIN.post(FIN.end(12),'CLS-'+d.tahun,'Jurnal penutup tahun '+d.tahun,c.l,'tutup')}d.lock=d.tahun+'-'+String(nm).padStart(2,'0');FIN.save();draw();toast(MN[nm-1]+' ditutup'+(d.ent.some(e=>e.src==='tutup')?' dan jurnal penutup diposting':''))};
  if($('#op'))$('#op').onclick=()=>{if(!confirm('Buka kembali '+MN[lm-1]+'? Periode akan bisa diubah lagi'+(lm===12&&d.ent.some(e=>e.src==='tutup')?' dan jurnal penutup tahun dihapus.':'.')))return;if(lm===12)d.ent=d.ent.filter(e=>e.src!=='tutup');d.lock=lm>1?d.tahun+'-'+String(lm-1).padStart(2,'0'):'';FIN.save();draw();toast(MN[lm-1]+' dibuka kembali')};
  if($('#pl'))$('#pl').onclick=()=>printDoc('Laporan '+MN[nm-1]+' '+d.tahun,lrBody(nm)+nrBody(nm));
};

/* ---------- PPh Pasal 23 & rekonsiliasi bank ---------- */
const PPH23=[
 {k:'jasa',n:'Jasa teknik, manajemen, konsultan, dan jasa lain (PMK 141/2015)',r:.02},
 {k:'sewa',n:'Sewa dan penggunaan harta selain tanah/bangunan',r:.02},
 {k:'royalti',n:'Royalti',r:.15},
 {k:'bunga',n:'Bunga selain bunga bank/obligasi',r:.15},
 {k:'hadiah',n:'Hadiah dan penghargaan selain yang dipotong PPh 21',r:.15}];
Object.assign(FIN,{
 ensure(){const d=this.d;if(!d)return;if(!d.coa.some(a=>a.k===2400)){d.coa.push({k:2400,n:'Utang PPh Pasal 23',t:'Liabilitas',g:'Liabilitas Jangka Pendek'});d.coa.sort((a,b)=>a.k-b.k)}
  d.pph23=d.pph23||[];d.bank=d.bank||{from:this.start(1),open:null,rows:[]}},
 bpNo(){return 'BP-'+String(this.d.pph23.reduce((m,x)=>Math.max(m,+x.no.slice(3)||0),0)+1).padStart(4,'0')},
 bpHit(jenis,dpp,nn){const J=PPH23.find(x=>x.k===jenis)||PPH23[0],r=J.r*(nn?2:1);return {r,v:Math.round((+dpp||0)*r)}},
 bpAdd(b){this.d.pph23.push(b);this.d.pph23.sort((x,y)=>x.d<y.d?-1:x.d>y.d?1:x.no<y.no?-1:1);this.post(b.d,b.no,'Potong PPh 23 '+b.c,[[b.db,b.pph,0],[2400,0,b.pph]],'pph23');if(b.ref)this.d.pays.push({d:b.d,jn:'Bayar',ref:b.ref,amt:b.pph,ak:2400,bp:b.no})},
 bpDel(b){const d=this.d;d.ent=d.ent.filter(e=>!(e.src==='pph23'&&e.no===b.no));d.pays=d.pays.filter(p=>p.bp!==b.no);d.pph23=d.pph23.filter(x=>x!==b)},
 setorNo(m){const ym=this.d.tahun+'-'+String(m).padStart(2,'0'),n=this.d.ent.filter(e=>e.src==='pph23s'&&e.no.startsWith('STR23-'+ym)).length;return 'STR23-'+ym+(n?'-'+(n+1):'')},
 setor(m,ak,date,ntpn){const L=this.d.pph23.filter(b=>b.d>=this.start(m)&&b.d<=this.end(m)&&!b.setor),v=L.reduce((s,b)=>s+b.pph,0);if(!v)return 0;const no=this.setorNo(m);this.post(date,no,'Setor PPh 23 masa '+MN[m-1]+' '+this.d.tahun,[[2400,v,0],[ak,0,v]],'pph23s');L.forEach(b=>b.setor={d:date,ntpn:ntpn||'',no});return v},
 unsetor(no){const d=this.d;d.ent=d.ent.filter(e=>!(e.src==='pph23s'&&e.no===no));d.pph23.forEach(b=>{if(b.setor&&b.setor.no===no)b.setor=null})},
 /* rekonsiliasi bank */
 bkBefore(from){const o=this.sums(null,iso(new Date(dt(from).getTime()-864e5)),true);return this.bal(o,1110)},
 bkLines(){const f=this.d.bank.from,cnt={},L=[];this.d.ent.forEach(e=>{if(e.d<f)return;e.l.forEach(([c,db,kr])=>{if(c!==1110||!(db||kr))return;const a=db-kr,b=e.no+'|'+e.d+'|'+a,n=cnt[b]=(cnt[b]||0)+1;L.push({k:b+'|'+n,d:e.d,no:e.no,ket:e.ket,amt:a,src:e.src})})});return L},
 bkState(m){const B=this.d.bank,end=this.end(m),lines=this.bkLines().filter(l=>l.d<=end),rows=B.rows.filter(r=>r.d>=B.from&&r.d<=end),map={};lines.forEach(l=>map[l.k]=l);
  const taken=new Set(),matched=[],bankOnly=[];rows.forEach(r=>{const l=r.m&&map[r.m]&&!taken.has(r.m)?map[r.m]:null;if(l){taken.add(l.k);matched.push({r,l})}else bankOnly.push(r)});
  const bookOnly=lines.filter(l=>!taken.has(l.k)),before=this.bkBefore(B.from),open=B.open==null?before:B.open,sum=a=>a.reduce((s,x)=>s+x.amt,0);
  const sBank=open+sum(rows),sBuku=before+sum(lines),transit=sum(bookOnly.filter(x=>x.amt>0)),outst=Math.abs(sum(bookOnly.filter(x=>x.amt<0))),bIn=sum(bankOnly.filter(x=>x.amt>0)),bOut=Math.abs(sum(bankOnly.filter(x=>x.amt<0)));
  const adjBank=sBank+transit-outst,adjBuku=sBuku+bIn-bOut;return {rows,lines,matched,bankOnly,bookOnly,before,open,sBank,sBuku,transit,outst,bIn,bOut,adjBank,adjBuku,selisih:Math.round(adjBank-adjBuku)}},
 bkAuto(m){const S=this.bkState(m),free=S.bookOnly.slice();let n=0;S.bankOnly.slice().sort((a,b)=>a.d<b.d?-1:1).forEach(r=>{let best=-1,bd=99;free.forEach((l,i)=>{if(l.amt!==r.amt)return;const dd=Math.abs(Math.round((dt(l.d)-dt(r.d))/864e5));if(dd<=5&&dd<bd){bd=dd;best=i}});if(best>=0){r.m=free[best].k;free.splice(best,1);n++}});return n},
 bkNo(){return 'B-'+String(this.d.bank.rows.reduce((m,x)=>Math.max(m,+x.id.slice(2)||0),0)+1).padStart(5,'0')},
 bkJurnal(r,akun,ket){const v=Math.abs(r.amt),no='RK-'+String(this.d.ent.filter(e=>e.src==='rekon').length+1).padStart(4,'0');this.post(r.d,no,ket||r.ket,r.amt<0?[[akun,v,0],[1110,0,v]]:[[1110,v,0],[akun,0,v]],'rekon');r.m=this.bkLines().find(l=>l.no===no).k;return no},
 seedExtra(){const d=this.d,B=d.bulan,R=(dd,c,jenis,dpp,nn)=>{const h=this.bpHit(jenis,dpp,nn);this.bpAdd({no:this.bpNo(),d:dd,c,npwp:nn?'':'09.876.543.2-012.000',nn:!!nn,jenis,dpp,r:h.r,pph:h.v,ref:'',db:6500,ket:'',setor:null})};
  d.pph23=[];d.bank={from:this.start(1),open:null,rows:[]};
  if(DEMO()){R(this.start(B).slice(0,8)+'05','CV Konsultan Pratama','jasa',15000000);R(this.start(B).slice(0,8)+'12','PT Gedung Sentosa','sewa',24000000);R(this.start(B).slice(0,8)+'20','Studio Kreatif Nusa','jasa',8500000,1)}
  else{const Y=m=>this.start(m).slice(0,8);[B-2,B-1,B].filter(m=>m>=1).forEach((m,i)=>{R(Y(m)+'06','CV Konsultan Pratama','jasa',15000000+i*1500000);R(Y(m)+'14','PT Gedung Sentosa','sewa',24000000);R(Y(m)+'21',['Studio Kreatif Nusa','KJPP Mitra Valuasi','PT Lisensi Digital'][i%3],i===2?'royalti':'jasa',[8500000,12000000,6000000][i],i===1)});
   [B-2,B-1].filter(m=>m>=1).forEach(m=>this.setor(m,1110,iso(new Date(d.tahun,m,9)),'NTPN'+(7200+m)))}
  /* mutasi bank contoh */
  const w=Math.max(1,B-1),from=this.start(w);d.bank.from=from;this.seedBank(w,B);
  for(let m=w;m<B;m++){this.bkAuto(m);this.bankOnlyPost(m)}},
 seedBank(w,B){const d=this.d,L=this.bkLines().filter(l=>l.d<=this.end(B)),rows=d.bank.rows;let i=0;const endB=this.end(B);
  L.forEach(l=>{i++;const late=l.d>iso(new Date(dt(endB).getTime()-4*864e5));if(late&&l.amt>0&&i%2===0)return;if(l.amt<0&&l.src!=='loan'&&i%9===4)return;let dd=l.d;const sh=i%5===1?1:i%7===3?2:0;if(sh){const x=iso(new Date(dt(dd).getTime()+sh*864e5));dd=x>endB?dd:x}rows.push({id:this.bkNo(),d:dd,ket:l.ket.slice(0,60),amt:l.amt,m:null})});
  for(let m=w;m<=B;m++){const e=this.end(m);rows.push({id:this.bkNo(),d:iso(new Date(dt(e).getTime()-864e5)),ket:'Biaya administrasi bank',amt:-15000,m:null});rows.push({id:this.bkNo(),d:e,ket:'Bunga jasa giro',amt:150000+m*3100,m:null})}
  rows.sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:a.id<b.id?-1:1)},
 bankOnlyPost(m){const S=this.bkState(m);S.bankOnly.forEach(r=>{if(r.amt<0&&/administrasi/i.test(r.ket))this.bkJurnal(r,6500,'Biaya administrasi bank');else if(r.amt>0&&/bunga/i.test(r.ket))this.bkJurnal(r,7200,'Bunga jasa giro')})}
});
{const _s=FIN.save,_i=FIN.init,_r=FIN.reset,_b=FIN.blank;
 FIN.save=function(){this.ensure();_s.call(this)};
 FIN.init=function(){_i.call(this);this.ensure()};
 FIN.reset=function(){_r.call(this);this.ensure();this.seedExtra();this.save()};
 FIN.blank=function(){_b.call(this);this.d.pph23=[];this.d.bank={from:this.start(1),open:null,rows:[]};this.save()}}

/* ----- tampilan PPh 23 ----- */
function bpDoc(b){const J=PPH23.find(x=>x.k===b.jenis)||PPH23[0],rw=(a,v)=>`<tr><td style="width:36%;color:#64748b">${a}</td><td>${v}</td></tr>`;
 return `<div class="pg">${docHead('Bukti Pemotongan PPh Pasal 23',b.no)}<table>${rw('Tanggal pemotongan',fdate(b.d))}${rw('Penerima penghasilan',esc(b.c))}${rw('NPWP / NIK',b.nn?'Tidak ada (tarif 2× lebih tinggi)':esc(b.npwp||'-'))}${rw('Jenis penghasilan',esc(J.n))}${rw('Dasar pengenaan pajak',idr(b.dpp))}${rw('Tarif',pct(b.r,b.r*100%1?1:0))}${rw('PPh Pasal 23 dipotong','<b>'+idr(b.pph)+'</b>')}${rw('Keterangan',esc(b.ket||'-'))}${rw('Status setoran',b.setor?'Disetor '+fdate(b.setor.d)+(b.setor.ntpn?' · NTPN '+esc(b.setor.ntpn):''):'Belum disetor')}</table><p style="font-size:11px;color:#64748b;margin-top:10px">Dokumen ini adalah catatan internal pemotongan. Bukti potong resmi dibuat dan dilaporkan melalui e-Bupot DJP.</p><div class="ttd"><div>Pemotong<br><br><br><br>(${esc(CO.get())})</div><div>Penerima penghasilan<br><br><br><br>(${esc(b.c)})</div></div></div>`}
function bpRekap(L,m){const t=L.reduce((s,b)=>s+b.pph,0),dpp=L.reduce((s,b)=>s+b.dpp,0);
 return `<div class="pg">${docHead('Rekap PPh Pasal 23',MN[m-1]+' '+FIN.d.tahun)}<table><thead><tr><th>No</th><th>Tanggal</th><th>Penerima</th><th>Jenis</th><th class="n">DPP</th><th class="n">Tarif</th><th class="n">PPh</th><th>Setor</th></tr></thead><tbody>${L.map(b=>`<tr><td>${b.no}</td><td>${fdate(b.d)}</td><td>${esc(b.c)}</td><td>${esc((PPH23.find(x=>x.k===b.jenis)||{}).n||'').split(' (')[0]}</td><td class="n">${fmt(b.dpp)}</td><td class="n">${pct(b.r,b.r*100%1?1:0)}</td><td class="n">${fmt(b.pph)}</td><td>${b.setor?fdate(b.setor.d):'-'}</td></tr>`).join('')}<tr><td colspan="4"><b>Total</b></td><td class="n"><b>${fmt(dpp)}</b></td><td></td><td class="n"><b>${fmt(t)}</b></td><td></td></tr></tbody></table><p style="font-size:11px;color:#64748b;margin-top:10px">Setor paling lambat tanggal 10 bulan berikutnya, pelaporan SPT Masa paling lambat tanggal 20 bulan berikutnya. Verifikasi dengan ketentuan perpajakan yang berlaku.</p></div>`}
